import{_ as a,o as t,c as s,a0 as i}from"./chunks/framework.t4Rf69I2.js";const u=JSON.parse('{"title":"Key Management","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/key-management.md","filePath":"en/guide/key-management.md","lastUpdated":1785233645000}'),n={name:"en/guide/key-management.md"};function r(o,e,l,d,h,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="key-management" tabindex="-1">Key Management <a class="header-anchor" href="#key-management" aria-label="Permalink to &quot;Key Management&quot;">​</a></h1><p>This document covers the password-to-key and Diceware mnemonic passphrase features of go-cipher-cli, and their interoperability with the <a href="https://tools.wcheer.com/" target="_blank" rel="noreferrer">web tool</a>.</p><h2 id="core-capabilities" tabindex="-1">Core Capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to &quot;Core Capabilities&quot;">​</a></h2><h3 id="password-to-key-enhance" tabindex="-1">Password to Key (enhance) <a class="header-anchor" href="#password-to-key-enhance" aria-label="Permalink to &quot;Password to Key (enhance)&quot;">​</a></h3><p>Takes a password at the &quot;human memory&quot; level and hardens it via the Argon2id slow function + HKDF-Expand(SHA-256) domain separation into a 256-bit high-entropy key. <strong>What is actually used for encryption/authentication is this key</strong>; the password is merely the raw material to generate it.</p><p>Byte-level interoperable with the web tool: the same &quot;password + salt suffix&quot; derives exactly the same key in both the CLI and the web client.</p><h3 id="diceware-mnemonic-passphrase-diceware" tabindex="-1">Diceware Mnemonic Passphrase (diceware) <a class="header-anchor" href="#diceware-mnemonic-passphrase-diceware" aria-label="Permalink to &quot;Diceware Mnemonic Passphrase (diceware)&quot;">​</a></h3><p>Uses the EFF large wordlist (7776 words) and cryptographically secure random dice rolls to generate memorable yet high-entropy passphrases.</p><h2 id="password-to-key-pipeline" tabindex="-1">Password-to-Key Pipeline <a class="header-anchor" href="#password-to-key-pipeline" aria-label="Permalink to &quot;Password-to-Key Pipeline&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Password + Salt Suffix</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>1. Fixed salt = &quot;Your_Super_Long_Fixed_Salt_String_Here_2026&quot;</span></span>
<span class="line"><span>   Full salt = fixed salt + user salt suffix</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>2. Argon2id(64MB/3 iterations/1 lane, output 64 bytes)</span></span>
<span class="line"><span>   → Master key PRK (512 bits)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>3. HKDF-Expand(SHA-256, PRK, domain=&quot;default-v1&quot;, output 32 bytes)</span></span>
<span class="line"><span>   → Subkey (256 bits)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>4. Output a 64-character hex string</span></span></code></pre></div><h3 id="fixed-salt" tabindex="-1">Fixed Salt <a class="header-anchor" href="#fixed-salt" aria-label="Permalink to &quot;Fixed Salt&quot;">​</a></h3><p>The first layer of fixed salt is hardcoded in the source (<code>Your_Super_Long_Fixed_Salt_String_Here_2026</code>), identical to the web client. Its purpose is to defeat generic rainbow tables — even if an attacker precomputes rainbow tables for all common passwords, they are invalidated by the presence of the fixed salt.</p><h3 id="salt-suffix" tabindex="-1">Salt Suffix <a class="header-anchor" href="#salt-suffix" aria-label="Permalink to &quot;Salt Suffix&quot;">​</a></h3><p>An optional second-layer salt provided by the user (e.g. site name, device name), concatenated with the fixed salt to serve as the Argon2id salt. Different salt suffixes derive distinct keys:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enhance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MyMaster@2024&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --salt-suffix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> google</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Output: 3aac7a86fd8c549020841738920154a05bcae6dd116c116a991144df33a440eb</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enhance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MyMaster@2024&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --salt-suffix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firefox</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Output: 12a642320091c23fe4d1ba943c86ba9a60ad99f2eba6ce4814636a4cdd664e6d</span></span></code></pre></div><p>Even if the Google key is leaked, the Firefox key remains secure.</p><h3 id="hkdf-expand-domain-separation" tabindex="-1">HKDF-Expand Domain Separation <a class="header-anchor" href="#hkdf-expand-domain-separation" aria-label="Permalink to &quot;HKDF-Expand Domain Separation&quot;">​</a></h3><p>The 64-byte master key (PRK) output by Argon2id is already uniformly distributed high-entropy data, so HKDF-Extract is skipped and pure Expand is used for domain separation. The internal domain label is fixed to <code>default-v1</code>.</p><h2 id="diceware-passphrase-generation" tabindex="-1">Diceware Passphrase Generation <a class="header-anchor" href="#diceware-passphrase-generation" aria-label="Permalink to &quot;Diceware Passphrase Generation&quot;">​</a></h2><h3 id="eff-wordlist" tabindex="-1">EFF Wordlist <a class="header-anchor" href="#eff-wordlist" aria-label="Permalink to &quot;EFF Wordlist&quot;">​</a></h3><p>Uses the large Diceware wordlist published by the EFF (Electronic Frontier Foundation) — 7776 English words, ordered by 5-dice rolls (11111–66666) in base-6 encoding:</p><ul><li>Roll <code>11111</code> → index 0 → <code>abacus</code></li><li>Roll <code>11112</code> → index 1 → <code>abdomen</code></li><li>...</li><li>Roll <code>66666</code> → index 7775 → <code>zoom</code></li></ul><h3 id="true-random-dice-rolls" tabindex="-1">True Random Dice Rolls <a class="header-anchor" href="#true-random-dice-rolls" aria-label="Permalink to &quot;True Random Dice Rolls&quot;">​</a></h3><p>Each word requires 5 dice rolls (1–6), each value sourced from the Go standard library <code>crypto/rand</code> (the OS CSPRNG). <strong>Rejection sampling</strong> eliminates modulo bias:</p><ul><li>Generate a random byte (0–255)</li><li>Only accept 0–251 (42 × 6), reject 252–255</li><li><code>byte % 6 + 1</code> yields 1–6</li></ul><p>This ensures each die value is strictly 1/6 probability, with no bias.</p><h3 id="entropy" tabindex="-1">Entropy <a class="header-anchor" href="#entropy" aria-label="Permalink to &quot;Entropy&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Words</th><th>Entropy</th><th>Possible Combinations</th><th>Security Level</th></tr></thead><tbody><tr><td>4</td><td>51.7 bit</td><td>3.66 × 10¹²</td><td>Weak (not recommended)</td></tr><tr><td>5</td><td>64.6 bit</td><td>2.84 × 10¹⁹</td><td>Basic</td></tr><tr><td>6</td><td>77.5 bit</td><td>2.21 × 10²³</td><td>Good</td></tr><tr><td>7</td><td>90.5 bit</td><td>1.72 × 10²⁷</td><td>Strong</td></tr><tr><td>8</td><td>103.4 bit</td><td>1.34 × 10³¹</td><td>Very strong</td></tr></tbody></table><p>At least 5 words are recommended. 8 words or more are suitable for scenarios demanding extremely high security.</p><h2 id="security-notes" tabindex="-1">Security Notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security Notes&quot;">​</a></h2><h3 id="argon2id-brute-force-resistance" tabindex="-1">Argon2id Brute-Force Resistance <a class="header-anchor" href="#argon2id-brute-force-resistance" aria-label="Permalink to &quot;Argon2id Brute-Force Resistance&quot;">​</a></h3><p>The 64MB memory / 3-iteration parameters make each derivation take several seconds, making brute-force attacks infeasible within a reasonable timeframe even with dedicated hardware. This is an award-winning algorithm from the Password Hashing Competition (PHC).</p><h3 id="fully-local-computation" tabindex="-1">Fully Local Computation <a class="header-anchor" href="#fully-local-computation" aria-label="Permalink to &quot;Fully Local Computation&quot;">​</a></h3><p>Passwords and keys are always computed locally on your operating system and never uploaded to any server.</p><h3 id="deterministic-derivation" tabindex="-1">Deterministic Derivation <a class="header-anchor" href="#deterministic-derivation" aria-label="Permalink to &quot;Deterministic Derivation&quot;">​</a></h3><p>The same &quot;password + salt suffix&quot; always yields the same key. There is no need to store the key itself — just remember the password to regenerate it at any time. The password cannot be reversed from the key.</p><h2 id="feature-mapping-with-the-web-tool" tabindex="-1">Feature Mapping with the Web Tool <a class="header-anchor" href="#feature-mapping-with-the-web-tool" aria-label="Permalink to &quot;Feature Mapping with the Web Tool&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>CLI Command</th><th>Web Tool Equivalent</th></tr></thead><tbody><tr><td>Password to key</td><td><code>enhance</code></td><td>Key Management → Password to Key</td></tr><tr><td>Diceware mnemonic passphrase</td><td><code>diceware</code></td><td>Key Management → Diceware Passphrase Generation</td></tr></tbody></table><h2 id="technical-details" tabindex="-1">Technical Details <a class="header-anchor" href="#technical-details" aria-label="Permalink to &quot;Technical Details&quot;">​</a></h2><h3 id="cross-language-consistency-guarantee" tabindex="-1">Cross-Language Consistency Guarantee <a class="header-anchor" href="#cross-language-consistency-guarantee" aria-label="Permalink to &quot;Cross-Language Consistency Guarantee&quot;">​</a></h3><p>The Go implementation of password-to-key passes 6 sets of <strong>golden vector tests</strong>:</p><ul><li>3 sets across different domains (age-key-v1 / file-key-v1 / auth-key-v1)</li><li>3 sets across different password + salt suffix combinations (weak password / strong password / Chinese password)</li></ul><p>All vectors are generated by the Go reference implementation; both the CLI and the web client must pass all of them to be considered correct.</p><h3 id="full-test-coverage" tabindex="-1">Full Test Coverage <a class="header-anchor" href="#full-test-coverage" aria-label="Permalink to &quot;Full Test Coverage&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./internal/...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># internal/kdf: TestDeriveSubKeyByDomain_GoldenVectors (6 vector sets)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># internal/diceware: wordlist integrity, dice roll mapping, passphrase generation, randomness, edge cases</span></span></code></pre></div>`,45)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
